-- ==========================================================================
-- FC9 RECUT, EXPERT TIER (advanced): Corrosion & Integrity (corrosion)
-- question bank brought to engines 16fd6c9 (#231).
--
-- WHY. Engines #231 (canonical 16fd6c9) adds a two-line comment to
-- engines/facilities/corrosion.js and moves no value. The LIVE FC9 bank quoted
-- facts about the engine SOURCE FILE ("783 lines", "five past-tense comment
-- lines", "one line in 157"), which the re-vendor makes false. Questions keyed
-- on a file's line count test nothing about corrosion, so the recut drops the
-- count wherever it was incidental and replaces the one question that keyed on
-- it with a question about what the sour flag tells an engineer.
--
-- WHAT MOVES. 5 of the 132 Expert questions, 2 with a changed keyed answer TEXT and 0 with a changed answer INDEX. No ord, no
-- module key, no scope and no row count moves, so every question id and every
-- learner attempt against it survives.
-- Fields rewritten: 3 explanation, 3 options, 1 prompt (7 field edits).
--
-- GUARDS. Each row is addressed by its stable identity (app_slug, tier, scope,
-- module_key, ord) and must match EITHER its published text exactly, in which
-- case it is updated, OR the recut text exactly, in which case it is already
-- applied and left alone. Anything else raises and the transaction rolls back.
-- Every update asserts it touched exactly 1 row, and the tier must still hold
-- 132 questions at the end.
--
-- The published strings are the rows 20260925_fc9_corrosion_advanced_deep.sql
-- wrote (APPLIED 2026-09-19), regenerated byte for byte from the committed banks
-- at origin/main d54538463. See docs/fc9-231-recut/RECUT-fc9-corrosion.json.
--
-- SAFE TO RE-RUN. A second run finds every row already carrying the recut
-- text and updates nothing.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
begin

  -- module m01-what-this-module-holds-back ord 2: explanation
  select case
           when prompt = 'The withdrawn sour-service severity region is not on `HELD_FOR_LITERATURE`, and `NOT_PROVIDED` names it marked withdrawn. Why is it not on the held list?' and options = '["It is not waiting for a source. The claim was withdrawn outright, and the engine also reports that absence through `regionProvided` and `materialGuidanceProvided`.", "It sits on a third exported list of withdrawn features, which the whole screening door returns alongside the other two so that a caller can render all three of them together.", "It is held rather than listed, because the region expression still runs on every screening and only the two standard names were stripped out of the strings it returns.", "It came off both lists when the threshold value was kept, since a module that still prints a screening threshold is still classifying severity at that threshold."]'::jsonb and answer_index = 0 and explanation = 'Both fields are false today and will stay false, so the absence arrives as a field and a caller cannot read it as an unset property. The region function is not exported and neither standard name appears anywhere in the 783 lines of the engine source.' then 'old'
           when prompt = 'The withdrawn sour-service severity region is not on `HELD_FOR_LITERATURE`, and `NOT_PROVIDED` names it marked withdrawn. Why is it not on the held list?' and options = '["It is not waiting for a source. The claim was withdrawn outright, and the engine also reports that absence through `regionProvided` and `materialGuidanceProvided`.", "It sits on a third exported list of withdrawn features, which the whole screening door returns alongside the other two so that a caller can render all three of them together.", "It is held rather than listed, because the region expression still runs on every screening and only the two standard names were stripped out of the strings it returns.", "It came off both lists when the threshold value was kept, since a module that still prints a screening threshold is still classifying severity at that threshold."]'::jsonb and answer_index = 0 and explanation = 'Both fields are false today and will stay false, so the absence arrives as a field and a caller cannot read it as an unset property. The region function is not exported and neither standard name appears anywhere in the engine source.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm01-what-this-module-holds-back'::text and ord = 2;
  if v_state is null then raise exception 'FC9 recut refused: no row for module m01-what-this-module-holds-back ord 2'; end if;
  if v_state = 'other' then raise exception 'FC9 recut refused: module m01-what-this-module-holds-back ord 2 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'The withdrawn sour-service severity region is not on `HELD_FOR_LITERATURE`, and `NOT_PROVIDED` names it marked withdrawn. Why is it not on the held list?', options = '["It is not waiting for a source. The claim was withdrawn outright, and the engine also reports that absence through `regionProvided` and `materialGuidanceProvided`.", "It sits on a third exported list of withdrawn features, which the whole screening door returns alongside the other two so that a caller can render all three of them together.", "It is held rather than listed, because the region expression still runs on every screening and only the two standard names were stripped out of the strings it returns.", "It came off both lists when the threshold value was kept, since a module that still prints a screening threshold is still classifying severity at that threshold."]'::jsonb, answer_index = 0, explanation = 'Both fields are false today and will stay false, so the absence arrives as a field and a caller cannot read it as an unset property. The region function is not exported and neither standard name appears anywhere in the engine source.'
     where app_slug = 'corrosion' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm01-what-this-module-holds-back'::text and ord = 2;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'FC9 recut refused: module m01-what-this-module-holds-back ord 2 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- module m06-what-this-engine-used-to-do ord 2: explanation
  select case
           when prompt = 'What did the pre-repair engine serve off that severity region?' and options = '["An inspection interval and a retirement thickness, both taken from the region the stream landed in, which is why neither appears in this module today.", "A rate category band for sour streams, which sat beside the CO2 band and is the reason the category bands are held rather than merely unsourced.", "A wall shear threshold for sour service, set below the 100.000000000000 Pa used elsewhere, which was withdrawn with the region it was derived from.", "Three named material recommendations: what steel to buy, when to control hardness and when to qualify weldments."]'::jsonb and answer_index = 3 and explanation = 'A curve that carries a standard''s name and tells an engineer what steel to buy is not a tolerance question. The three strings are gone and none of them appears anywhere in the 783 lines of the engine source.' then 'old'
           when prompt = 'What did the pre-repair engine serve off that severity region?' and options = '["An inspection interval and a retirement thickness, both taken from the region the stream landed in, which is why neither appears in this module today.", "A rate category band for sour streams, which sat beside the CO2 band and is the reason the category bands are held rather than merely unsourced.", "A wall shear threshold for sour service, set below the 100.000000000000 Pa used elsewhere, which was withdrawn with the region it was derived from.", "Three named material recommendations: what steel to buy, when to control hardness and when to qualify weldments."]'::jsonb and answer_index = 3 and explanation = 'A curve that carries a standard''s name and tells an engineer what steel to buy is not a tolerance question. The three strings are gone and none of them appears anywhere in the engine source.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm06-what-this-engine-used-to-do'::text and ord = 2;
  if v_state is null then raise exception 'FC9 recut refused: no row for module m06-what-this-engine-used-to-do ord 2'; end if;
  if v_state = 'other' then raise exception 'FC9 recut refused: module m06-what-this-engine-used-to-do ord 2 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'What did the pre-repair engine serve off that severity region?', options = '["An inspection interval and a retirement thickness, both taken from the region the stream landed in, which is why neither appears in this module today.", "A rate category band for sour streams, which sat beside the CO2 band and is the reason the category bands are held rather than merely unsourced.", "A wall shear threshold for sour service, set below the 100.000000000000 Pa used elsewhere, which was withdrawn with the region it was derived from.", "Three named material recommendations: what steel to buy, when to control hardness and when to qualify weldments."]'::jsonb, answer_index = 3, explanation = 'A curve that carries a standard''s name and tells an engineer what steel to buy is not a tolerance question. The three strings are gone and none of them appears anywhere in the engine source.'
     where app_slug = 'corrosion' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm06-what-this-engine-used-to-do'::text and ord = 2;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'FC9 recut refused: module m06-what-this-engine-used-to-do ord 2 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- module m06-what-this-engine-used-to-do ord 5: options KEYED ANSWER TEXT CHANGED
  select case
           when prompt = 'The absence of the severity region is proved three ways. What are they?' and options = '["The region function is not exported so its type is undefined, neither standard name appears in the 783 lines of source, and no returned string in three whole screenings names either standard.", "The region function throws when it is called, the two standard names appear only inside comments, and the studio renders the absence behind the same disclosure as the held list.", "The engine exports two false flags, the golden carries no region row among its 110, and the vendored jest suite asserts that a region request refuses with a message naming the standard.", "The held list omits the region, the not-provided list names it twice, and the pin table has no row for the boundary constants of the region expression."]'::jsonb and answer_index = 0 and explanation = 'Each is a separate check. The two flags are how the engine states the absence, and the three proofs are how the digest established that the function and its strings have actually gone rather than been hidden.' then 'old'
           when prompt = 'The absence of the severity region is proved three ways. What are they?' and options = '["The region function is not exported so its type is undefined, neither standard name appears anywhere in the source, and no returned string in three whole screenings names either standard.", "The region function throws when it is called, the two standard names appear only inside comments, and the studio renders the absence behind the same disclosure as the held list.", "The engine exports two false flags, the golden carries no region row among its 110, and the vendored jest suite asserts that a region request refuses with a message naming the standard.", "The held list omits the region, the not-provided list names it twice, and the pin table has no row for the boundary constants of the region expression."]'::jsonb and answer_index = 0 and explanation = 'Each is a separate check. The two flags are how the engine states the absence, and the three proofs are how the digest established that the function and its strings have actually gone rather than been hidden.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm06-what-this-engine-used-to-do'::text and ord = 5;
  if v_state is null then raise exception 'FC9 recut refused: no row for module m06-what-this-engine-used-to-do ord 5'; end if;
  if v_state = 'other' then raise exception 'FC9 recut refused: module m06-what-this-engine-used-to-do ord 5 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'The absence of the severity region is proved three ways. What are they?', options = '["The region function is not exported so its type is undefined, neither standard name appears anywhere in the source, and no returned string in three whole screenings names either standard.", "The region function throws when it is called, the two standard names appear only inside comments, and the studio renders the absence behind the same disclosure as the held list.", "The engine exports two false flags, the golden carries no region row among its 110, and the vendored jest suite asserts that a region request refuses with a message naming the standard.", "The held list omits the region, the not-provided list names it twice, and the pin table has no row for the boundary constants of the region expression."]'::jsonb, answer_index = 0, explanation = 'Each is a separate check. The two flags are how the engine states the absence, and the three proofs are how the digest established that the function and its strings have actually gone rather than been hidden.'
     where app_slug = 'corrosion' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm06-what-this-engine-used-to-do'::text and ord = 5;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'FC9 recut refused: module m06-what-this-engine-used-to-do ord 5 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- final final ord 8: options
  select case
           when prompt = 'A reader wants to know whether this engine actually uses the value it exports for a constant. What answers that, and what does not?' and options = '["Reading the export answers it, because an exported name is the value the functions close over and there is no second copy anywhere in a module of 783 lines.", "A measurement of the behaviour answers it. Reading the export answers only what the module declares about itself.", "Comparing the export against the golden''s `heldConstants` block answers it, because the golden was generated by running the engine rather than by reading it.", "Neither answers it, which is why the digest prints both columns."]'::jsonb and answer_index = 1 and explanation = 'The two can differ through a second copy inside a function, a branch that never reaches the exported name, or a value transformed on the way in. Nothing in this module currently separates, and that is a result with a size attached.' then 'old'
           when prompt = 'A reader wants to know whether this engine actually uses the value it exports for a constant. What answers that, and what does not?' and options = '["Reading the export answers it, because an exported name is the value the functions close over and there is no second copy anywhere in a module that imports nothing.", "A measurement of the behaviour answers it. Reading the export answers only what the module declares about itself.", "Comparing the export against the golden''s `heldConstants` block answers it, because the golden was generated by running the engine rather than by reading it.", "Neither answers it, which is why the digest prints both columns."]'::jsonb and answer_index = 1 and explanation = 'The two can differ through a second copy inside a function, a branch that never reaches the exported name, or a value transformed on the way in. Nothing in this module currently separates, and that is a result with a size attached.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null::text and ord = 8;
  if v_state is null then raise exception 'FC9 recut refused: no row for final final ord 8'; end if;
  if v_state = 'other' then raise exception 'FC9 recut refused: final final ord 8 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'A reader wants to know whether this engine actually uses the value it exports for a constant. What answers that, and what does not?', options = '["Reading the export answers it, because an exported name is the value the functions close over and there is no second copy anywhere in a module that imports nothing.", "A measurement of the behaviour answers it. Reading the export answers only what the module declares about itself.", "Comparing the export against the golden''s `heldConstants` block answers it, because the golden was generated by running the engine rather than by reading it.", "Neither answers it, which is why the digest prints both columns."]'::jsonb, answer_index = 1, explanation = 'The two can differ through a second copy inside a function, a branch that never reaches the exported name, or a value transformed on the way in. Nothing in this module currently separates, and that is a result with a size attached.'
     where app_slug = 'corrosion' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null::text and ord = 8;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'FC9 recut refused: final final ord 8 updated % rows', v_count; end if;
