  end if;

  -- final final ord 38: prompt, options, explanation KEYED ANSWER TEXT CHANGED
  select case
           when prompt = 'A sentence lifted out of an engine source comment arrives with no frame around it. How many of this module''s comment lines are written in a past tense about former behaviour?' and options = '["Five, in a module of 783 lines, and none of them carries a repair marker.", "Eleven, one for each held item, and each one carries a repair marker naming the change that removed the behaviour it describes for a reader of the source.", "None, because the repair stripped every past-tense comment out of the module and moved the history into the digest section that carries the frame for it.", "Eight, matching the entries in the not-provided list, and each one records the behaviour that stood where the absence is now declared."]'::jsonb and answer_index = 0 and explanation = 'Roughly one line in 157 of the module carries a past-tense sentence about former behaviour. Engine source comments are provenance, and so are the wave recon and findings reports and the repair record vendored beside the oracle.' then 'old'
           when prompt = 'A stream screens above the 0.003500000000 bar H2S threshold. What does this module tell the engineer about the steel for the line?' and options = '["That the stream is sour by the screening comparison and nothing more. Which material qualifies has to come from a sour-service assessment made outside this module.", "That carbon steel is acceptable up to the first region boundary, since the threshold marks the lower edge of the mildest band the engine still classifies against.", "That a corrosion resistant alloy is required, because any stream above the threshold lands in the hardest recommendation the module returns for a sour regime.", "That the choice follows from the H2S to CO2 ratio, since the regime word the engine returns beside the sour flag names the material family to specify."]'::jsonb and answer_index = 0 and explanation = 'The sour flag is a comparison against one held number. The severity region and its three material recommendations were withdrawn, and the engine reports that through `regionProvided` and `materialGuidanceProvided`, both false.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null::text and ord = 38;
  if v_state is null then raise exception 'FC9 recut refused: no row for final final ord 38'; end if;
  if v_state = 'other' then raise exception 'FC9 recut refused: final final ord 38 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'A stream screens above the 0.003500000000 bar H2S threshold. What does this module tell the engineer about the steel for the line?', options = '["That the stream is sour by the screening comparison and nothing more. Which material qualifies has to come from a sour-service assessment made outside this module.", "That carbon steel is acceptable up to the first region boundary, since the threshold marks the lower edge of the mildest band the engine still classifies against.", "That a corrosion resistant alloy is required, because any stream above the threshold lands in the hardest recommendation the module returns for a sour regime.", "That the choice follows from the H2S to CO2 ratio, since the regime word the engine returns beside the sour flag names the material family to specify."]'::jsonb, answer_index = 0, explanation = 'The sour flag is a comparison against one held number. The severity region and its three material recommendations were withdrawn, and the engine reports that through `regionProvided` and `materialGuidanceProvided`, both false.'
     where app_slug = 'corrosion' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null::text and ord = 38;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'FC9 recut refused: final final ord 38 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_count from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'advanced';
  if v_count <> 132 then raise exception 'FC9 recut refused: corrosion advanced holds % questions, expected 132', v_count; end if;
  raise notice 'FC9 recut advanced: % of 5 rows updated, % already recut', v_updated, 5 - v_updated;
